-- Assign stable, client-catalogued Material icon keys to the built-in
-- marketplace categories. The initial category seed predates icon_key, so
-- those rows otherwise retain the schema default ('category').
--
-- This is reference data only: it neither creates nor changes accounts,
-- listings, stores, media, roles, or Storage objects. Existing admin-created
-- categories are intentionally not touched.
begin;

update public.categories
set icon_key = case id
  when '10000000-0000-4000-8000-000000000001'::uuid then 'restaurant'
  when '10000000-0000-4000-8000-000000000002'::uuid then 'local_cafe'
  when '10000000-0000-4000-8000-000000000003'::uuid then 'car_repair'
  when '10000000-0000-4000-8000-000000000004'::uuid then 'restaurant'
  when '10000000-0000-4000-8000-000000000005'::uuid then 'restaurant'
  when '10000000-0000-4000-8000-000000000006'::uuid then 'storefront'
  when '10000000-0000-4000-8000-000000000007'::uuid then 'beauty'
  when '10000000-0000-4000-8000-000000000008'::uuid then 'pets'
  when '10000000-0000-4000-8000-000000000009'::uuid then 'medication'
  when '10000000-0000-4000-8000-000000000010'::uuid then 'phone_android'
  when '10000000-0000-4000-8000-000000000011'::uuid then 'devices'
  when '10000000-0000-4000-8000-000000000012'::uuid then 'checkroom'
  when '10000000-0000-4000-8000-000000000013'::uuid then 'home'
  when '10000000-0000-4000-8000-000000000014'::uuid then 'handyman'
  when '10000000-0000-4000-8000-000000000015'::uuid then 'more_horiz'
  when '20000000-0000-4000-8000-000000000001'::uuid then 'directions_car'
  when '20000000-0000-4000-8000-000000000002'::uuid then 'phone_android'
  when '20000000-0000-4000-8000-000000000003'::uuid then 'home'
  when '20000000-0000-4000-8000-000000000004'::uuid then 'checkroom'
  when '20000000-0000-4000-8000-000000000005'::uuid then 'hardware'
  when '20000000-0000-4000-8000-000000000006'::uuid then 'fastfood'
  when '20000000-0000-4000-8000-000000000007'::uuid then 'devices'
  when '20000000-0000-4000-8000-000000000008'::uuid then 'more_horiz'
  else icon_key
end
where id in (
  '10000000-0000-4000-8000-000000000001'::uuid,
  '10000000-0000-4000-8000-000000000002'::uuid,
  '10000000-0000-4000-8000-000000000003'::uuid,
  '10000000-0000-4000-8000-000000000004'::uuid,
  '10000000-0000-4000-8000-000000000005'::uuid,
  '10000000-0000-4000-8000-000000000006'::uuid,
  '10000000-0000-4000-8000-000000000007'::uuid,
  '10000000-0000-4000-8000-000000000008'::uuid,
  '10000000-0000-4000-8000-000000000009'::uuid,
  '10000000-0000-4000-8000-000000000010'::uuid,
  '10000000-0000-4000-8000-000000000011'::uuid,
  '10000000-0000-4000-8000-000000000012'::uuid,
  '10000000-0000-4000-8000-000000000013'::uuid,
  '10000000-0000-4000-8000-000000000014'::uuid,
  '10000000-0000-4000-8000-000000000015'::uuid,
  '20000000-0000-4000-8000-000000000001'::uuid,
  '20000000-0000-4000-8000-000000000002'::uuid,
  '20000000-0000-4000-8000-000000000003'::uuid,
  '20000000-0000-4000-8000-000000000004'::uuid,
  '20000000-0000-4000-8000-000000000005'::uuid,
  '20000000-0000-4000-8000-000000000006'::uuid,
  '20000000-0000-4000-8000-000000000007'::uuid,
  '20000000-0000-4000-8000-000000000008'::uuid
);

commit;
